const css="body{font:16px system-ui,sans-serif;color:#17243a;background:linear-gradient(145deg,#eaf2ff,#f8fafc 48%,#e9f8f3);min-height:100vh;margin:0}*{box-sizing:border-box}header,main,footer{max-width:1080px;margin:auto;padding:24px}header{display:flex;align-items:center;flex-wrap:wrap;gap:14px;border-bottom:1px solid #e2e8f0}header a:first-child{font-size:23px;font-weight:900;letter-spacing:-1px;margin-right:auto}a{color:#2456a6;text-decoration:none}a:hover{text-decoration:underline}h1{font-size:clamp(30px,5vw,46px);letter-spacing:-1.5px;margin:24px 0 10px}h2{font-size:23px;margin-top:36px}p{line-height:1.7;color:#52647b}nav{display:grid;grid-template-columns:repeat(auto-fit,minmax(190px,1fr));gap:12px}nav a{background:white;border:1px solid #e0e7f0;border-radius:10px;padding:16px;font-weight:650}.panel{background:white;border:1px solid #dce4ef;border-radius:16px;padding:clamp(18px,4vw,36px);border-top:4px solid #3568b8;box-shadow:0 12px 36px #183b8012;margin:28px 0}label{display:block;margin:16px 0;font-weight:600}label[hidden]{display:none}input,textarea{width:100%;padding:14px;border:1px solid #c5d3e8;border-radius:8px;font:inherit;margin-top:8px;background:#fff;color:#17243a}input[type=file]{border:2px dashed #a9bddb;padding:24px;background:#f3f7ff}button{background:linear-gradient(120deg,#163b80,#2866b7);color:white;padding:14px 24px;border:0;border-radius:9px;font:inherit;font-weight:700;cursor:pointer}button:disabled{opacity:.6}pre{white-space:pre-wrap;overflow-wrap:anywhere;background:#eef4ff;border-radius:8px;padding:16px;color:#163b80}pre:not(:empty){border:1px solid #a9c9e8;border-left:4px solid #168779;font-size:18px;line-height:1.8;font-weight:600;animation:resultIn .2s ease-out}pre:empty{display:none}@keyframes resultIn{from{opacity:0;transform:translateY(5px)}to{opacity:1;transform:translateY(0)}}button:active{transform:scale(.98)}button:focus-visible{outline:3px solid #168779;outline-offset:3px}footer{border-top:1px solid #e2e8f0;color:#64748b;font-size:14px}@media(max-width:600px){header,main,footer{padding:16px}header a:first-child{width:100%}nav{grid-template-columns:repeat(2,minmax(0,1fr))}nav a{padding:12px;font-size:14px}}";
const professionalCss="body{background:#f4f7fb}header{background:#fff;border-bottom:1px solid #dce5f0;border-radius:0 0 16px 16px}main{max-width:1080px}h1{color:#12284c}main>p{max-width:760px}.panel{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:18px;border-top:4px solid #2456a6;box-shadow:0 12px 40px #12284c0d}.panel label{margin:0;font-size:14px;color:#334155}.panel label:has(textarea),.panel label:has(input[type=file]),.panel button,.panel pre,.panel nav{grid-column:1/-1}.panel input,.panel textarea{background:#f8fafc;border-color:#cbd5e1;transition:border-color .15s,box-shadow .15s}.panel input:focus,.panel textarea:focus{outline:none;border-color:#3568b8;box-shadow:0 0 0 3px #3568b822}.panel button{min-height:50px;background:#2456a6;transition:background .15s,transform .15s}.panel button:hover{background:#173b78}.panel pre:not(:empty){margin:0;background:#edf8f4;color:#115e50;border-color:#b8dfd2;padding:22px;font:600 18px/1.8 system-ui,sans-serif}.panel pre:focus{outline:2px solid #168779;outline-offset:3px}nav a{transition:box-shadow .15s,border-color .15s}nav a:hover{border-color:#7394c7;box-shadow:0 4px 16px #12284c10;text-decoration:none}footer{background:#12284c;color:#e2e8f0;border-radius:16px 16px 0 0;margin-top:36px} @media(max-width:600px){.panel{grid-template-columns:1fr;gap:14px}.panel button{width:100%}h1{letter-spacing:-.8px}}@media(prefers-reduced-motion:reduce){*{animation:none!important;transition:none!important;scroll-behavior:auto!important}}";
