function page(slug,title,desc,body,kind=''){if(slug==='learn'||slug.startsWith('learn/'))kind='learn';const schema=kind?'<script type="application/ld+json">'+JSON.stringify({'@context':'https://schema.org','@type':'WebApplication',name:title,url:base+'/'+slug+'/',description:desc,applicationCategory:'UtilitiesApplication',operatingSystem:'Any',offers:{'@type':'Offer',price:0,priceCurrency:'INR'}})+'</script>':'';const dir=path.join(root,slug);fs.mkdirSync(dir,{recursive:true});fs.writeFileSync(path.join(dir,'index.html'),'<!doctype html><html lang="en-IN"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>'+title+' | USETOOLBENCH</title><meta name="description" content="'+desc+'"><link rel="canonical" href="'+base+'/'+slug+'/"><meta property="og:title" content="'+title+'"><meta property="og:description" content="'+desc+'">'+schema+'<style>'+css+professionalCss+learnCss+'</style></head><body data-kind="'+kind+'"><header><a href="/">USETOOLBENCH</a> · <a href="/tools/">All tools</a> · <a href="/pdf-tools/">PDF tools</a> · <a href="/learn/">Learn</a> · <a href="/privacy/">Privacy</a> · <a href="/about/">About</a> · <a href="/terms/">Terms</a></header>'+ (kind==='learn'?'<div class="coursebar"><a href="/learn/">Tutorials</a><a href="/learn/html/">HTML</a><a href="/learn/css/">CSS</a><a href="/learn/javascript/">JavaScript</a><a href="/learn/sql/">SQL</a><a href="/learn/python/">Python</a><a href="/learn/excel/">Excel</a><a href="/learn/sap-b1/">SAP B1</a><a href="/learn/sap-s4hana/">SAP S/4HANA</a></div>':'') +'<main><h1>'+title+'</h1><p>'+desc+'</p>'+body+'<h2>Explore more tools</h2><nav>'+links+'</nav></main><footer>USETOOLBENCH · Estimates are informational, not financial advice.</footer></body></html>');}
