const sapModules=[["fi","FI – Financial Accounting","General ledger, accounts payable, accounts receivable, asset accounting and closing.","Post a supplier invoice: debit expense or inventory clearing as applicable, credit supplier."],["co","CO – Controlling","Cost centers, profit centers, internal orders, product costing and profitability analysis.","Assign an expense to a cost center and review actual versus plan."],["mm","MM – Materials Management","Purchasing, inventory management, material master and invoice verification.","Purchase requisition → purchase order → goods receipt → invoice verification."],["sd","SD – Sales and Distribution","Sales orders, pricing, delivery, billing and credit management.","Sales order → outbound delivery → goods issue → billing."],["pp","PP – Production Planning","BOM, routing, MRP, production orders and confirmations.","Run MRP, create a production order, issue components and receive finished goods."],["qm","QM – Quality Management","Inspection plans, inspection lots, results and usage decisions.","Record inspection results for a goods receipt and make a usage decision."],["pm","Asset Management (PM/EAM)","Equipment, functional locations, notifications and maintenance orders.","Create a maintenance notification and plan corrective maintenance."],["ewm","Extended Warehouse Management","Inbound and outbound warehouse processes, storage bins and warehouse tasks.","Receive goods, create a putaway task and confirm the destination bin."],["tm","Transportation Management","Freight planning, freight orders and settlement.","Plan transportation for outbound deliveries and create a freight order."],["ps","Project System","WBS elements, networks, budgeting and project settlement.","Create a WBS structure and assign project costs."],["aa","Asset Accounting (FI-AA)","Asset acquisition, depreciation, transfers and retirement.","Acquire an asset and review planned depreciation."],["treasury","Treasury and Risk Management","Cash management, financial instruments and risk analysis.","Review cash positions and forecast liquidity."],["gr","Group Reporting","Financial consolidation, intercompany elimination and group reporting.","Prepare consolidation data and eliminate intercompany balances."],["service","Service Management","Service contracts, service orders, execution and billing.","Create a service order and confirm work performed."],["aATP","Advanced Available-to-Promise","Product availability checks, allocation and backorder processing.","Check requested delivery quantities against available supply."],["mdg","Master Data Governance","Governance workflows, validation and master data quality.","Submit a business partner change request for approval."],["fiori","SAP Fiori","Role-based applications, launchpad and user experience.","Locate an authorized business app and review its filters."],["abap","ABAP and Extensibility","ABAP development, CDS views, RAP and clean-core extensions.","Define a read-only CDS view in an authorized development environment."],["basis","Basis and Security","System administration, authorizations, transports and monitoring.","Review a role assignment and transport request in a test system."],["analytics","Embedded Analytics","CDS analytical queries, KPIs and operational reporting.","Review a sales or inventory analytical report."],["hcm","HR and SuccessFactors Integration","Employee data and integration with HR solutions; deployment scope varies.","Review employee master integration requirements."],["grc","Governance, Risk and Compliance","Access risk analysis, segregation of duties and controls; separate solutions may be required.","Identify conflicting purchasing and payment permissions."]];
const sapLinks='<nav>'+sapModules.map(([slug,title])=>'<a href="/learn/sap-s4hana/'+slug.toLowerCase()+'/">'+esc(title)+'</a>').join('')+'</nav>';
