for(const [slug,title,desc,query] of b1Topics){page('learn/sap-b1/'+slug,'SAP B1 '+title,desc,'<div class="lesson-layout"><aside>'+b1Nav+'</aside><article><h2>'+esc(title)+'</h2><p>'+esc(desc)+'</p><h2>SQL Server example</h2><pre id="sql-example">'+esc(query)+'</pre><div style="display:flex;justify-content:flex-end;margin-top:10px"><button type="button" id="copy-sql">Copy SQL query</button></div><p id="copy-status" role="status"></p><script>document.getElementById("copy-sql").onclick=async()=>{try{await navigator.clipboard.writeText(document.getElementById("sql-example").textContent);document.getElementById("copy-status").textContent="Query copied"}catch(e){document.getElementById("copy-status").textContent="Select and copy the query manually."}}</script><h2>Practice</h2><p>Run the example in the appropriate authorized SAP B1 environment. Query Manager placeholders and FMS references are SAP-specific and do not run unchanged in SSMS. Results depend on your company data and configuration.</p></article></div>');}
page('learn/sap-b1/sql-practice','SAP B1 SQL Practice Playground','Practice SELECT queries with sample SAP Business One tables.',"<div class=\"lesson-layout\"><aside><h2>Practice tables</h2><div style=\"max-height:480px;overflow:auto;font-size:13px\"><p><strong>OCRD</strong> – Business Partner Master Data</p><p><strong>OITM</strong> – Item Master Data</p><p><strong>ORDR</strong> – Sales Order</p><p><strong>RDR1</strong> – Sales Order Rows</p><p><strong>OQUT</strong> – Sales Quotation</p><p><strong>QUT1</strong> – Sales Quotation Rows</p><p><strong>ODLN</strong> – Delivery</p><p><strong>DLN1</strong> – Delivery Rows</p><p><strong>OINV</strong> – A/R Invoice</p><p><strong>INV1</strong> – A/R Invoice Rows</p><p><strong>ORIN</strong> – A/R Credit Memo</p><p><strong>RIN1</strong> – A/R Credit Memo Rows</p><p><strong>OPRQ</strong> – Purchase Request</p><p><strong>PRQ1</strong> – Purchase Request Rows</p><p><strong>OPOR</strong> – Purchase Order</p><p><strong>POR1</strong> – Purchase Order Rows</p><p><strong>OPDN</strong> – Goods Receipt PO</p><p><strong>PDN1</strong> – Goods Receipt PO Rows</p><p><strong>OPCH</strong> – A/P Invoice</p><p><strong>PCH1</strong> – A/P Invoice Rows</p><p><strong>ORPC</strong> – A/P Credit Memo</p><p><strong>RPC1</strong> – A/P Credit Memo Rows</p><p><strong>OIGN</strong> – Goods Receipt</p><p><strong>IGN1</strong> – Goods Receipt Rows</p><p><strong>OIGE</strong> – Goods Issue</p><p><strong>IGE1</strong> – Goods Issue Rows</p><p><strong>OWTR</strong> – Inventory Transfer</p><p><strong>WTR1</strong> – Inventory Transfer Rows</p><p><strong>ODRF</strong> – Document Drafts</p><p><strong>DRF1</strong> – Document Draft Rows</p><p><strong>OWHS</strong> – Warehouses</p><p><strong>OITW</strong> – Item Warehouse Data</p><p><strong>OITB</strong> – Item Groups</p><p><strong>OACT</strong> – Chart of Accounts</p><p><strong>OJDT</strong> – Journal Entry</p><p><strong>JDT1</strong> – Journal Entry Rows</p><p><strong>ORCT</strong> – Incoming Payments</p><p><strong>RCT2</strong> – Incoming Payment Invoices</p><p><strong>OVPM</strong> – Outgoing Payments</p><p><strong>VPM2</strong> – Outgoing Payment Invoices</p><p><strong>OWOR</strong> – Production Order</p><p><strong>WOR1</strong> – Production Order Rows</p><p><strong>OITT</strong> – Bill of Materials</p><p><strong>ITT1</strong> – Bill of Materials Components</p><p><strong>OSLP</strong> – Sales Employees</p><p><strong>OHEM</strong> – Employee Master Data</p><p><strong>OCTG</strong> – Payment Terms</p><p><strong>ORTT</strong> – Exchange Rates</p><p><strong>OITR</strong> – Internal Reconciliation</p><p><strong>ITR1</strong> – Internal Reconciliation Rows</p><p><strong>NNM1</strong> – Document Numbering Series</p><p><strong>OSCL</strong> – Service Calls</p><p><strong>OADM</strong> – Company Details <small>(reference only)</small></p><p><strong>OUSR</strong> – Users <small>(reference only)</small></p><p><strong>OUBR</strong> – Branches <small>(reference only)</small></p><p><strong>CRD1</strong> – Business Partner Addresses <small>(reference only)</small></p><p><strong>OCPR</strong> – Contact Persons <small>(reference only)</small></p><p><strong>OCRG</strong> – Business Partner Groups <small>(reference only)</small></p><p><strong>OPQT</strong> – Purchase Quotation <small>(reference only)</small></p><p><strong>PQT1</strong> – Purchase Quotation Rows <small>(reference only)</small></p><p><strong>OINM</strong> – Inventory Journal <small>(reference only)</small></p><p><strong>OIVL</strong> – Inventory Valuation Log <small>(reference only)</small></p><p><strong>OBTN</strong> – Batch Numbers <small>(reference only)</small></p><p><strong>OBTQ</strong> – Batch Quantities <small>(reference only)</small></p><p><strong>OSRN</strong> – Serial Numbers <small>(reference only)</small></p><p><strong>OSRQ</strong> – Serial Quantities <small>(reference only)</small></p><p><strong>OITL</strong> – Inventory Transaction Log <small>(reference only)</small></p><p><strong>ITL1</strong> – Inventory Transaction Log Details <small>(reference only)</small></p><p><strong>OSTC</strong> – Tax Codes <small>(reference only)</small></p><p><strong>STC1</strong> – Tax Code Details <small>(reference only)</small></p><p><strong>OSTT</strong> – Tax Types <small>(reference only)</small></p><p><strong>INV4</strong> – A/R Invoice Tax Details <small>(reference only)</small></p><p><strong>PCH4</strong> – A/P Invoice Tax Details <small>(reference only)</small></p><p><strong>OACS</strong> – Asset Classes <small>(reference only)</small></p><p><strong>OADT</strong> – Asset Depreciation Types <small>(reference only)</small></p><p><strong>OUDP</strong> – Departments <small>(reference only)</small></p><p><strong>OHPS</strong> – Employee Positions <small>(reference only)</small></p><p><strong>OINS</strong> – Customer Equipment Cards <small>(reference only)</small></p><p><strong>OCTR</strong> – Service Contracts <small>(reference only)</small></p><p><strong>CUFD</strong> – User Defined Fields <small>(reference only)</small></p><p><strong>UFD1</strong> – User Defined Field Values <small>(reference only)</small></p><p><strong>OUTB</strong> – User Defined Tables <small>(reference only)</small></p><p><strong>OUDO</strong> – User Defined Objects <small>(reference only)</small></p><p><strong>OBPL</strong> – Business Places <small>(reference only)</small></p><p><strong>OCRY</strong> – Countries <small>(reference only)</small></p><p><strong>OCST</strong> – States <small>(reference only)</small></p><p><strong>OUOM</strong> – Units of Measure <small>(reference only)</small></p><p><strong>OUGP</strong> – Unit of Measure Groups <small>(reference only)</small></p><p><strong>UGP1</strong> – Unit of Measure Group Rows <small>(reference only)</small></p><p><strong>OOCR</strong> – Distribution Rules <small>(reference only)</small></p><p><strong>OPRC</strong> – Cost Centers <small>(reference only)</small></p><p><strong>OPRJ</strong> – Projects <small>(reference only)</small></p><p><strong>OALT</strong> – Alerts <small>(reference only)</small></p><p><strong>OCLG</strong> – Activities <small>(reference only)</small></p><p><strong>OATC</strong> – Attachments <small>(reference only)</small></p><p><strong>ATC1</strong> – Attachment Rows <small>(reference only)</small></p></div><a href=\"/learn/sap-b1/query-manager/\">Query Manager tutorial</a><h2>Stored procedure reference (SQL Server)</h2><p>Stored procedures require a real SQL Server backend. The browser practice engine cannot execute them.</p><pre>CREATE PROCEDURE dbo.GetSalesOrders\nAS\nBEGIN\n    SELECT * FROM ORDR;\nEND;</pre><pre>EXEC dbo.GetSalesOrders;</pre><p>SBO_SP_TransactionNotification: validate documents before commit. SBO_SP_PostTransactionNotice: post-transaction notification.</p></aside><article><p>Run real SQL against fictional SAP-style sample data. This browser sandbox uses SQLite, not Microsoft SQL Server. T-SQL functions and SAP parameters may not work.</p><label>Browse sample table (Table Code – Full Name)<select id=\"sql-table\" style=\"width:100%;padding:12px\"><option value=\"\">Choose table</option></select></label><label>SQL Editor <span id=\"sql-selected-name\" style=\"display:block;color:#2456a6;font-size:14px;margin:6px 0\">ORDR – Sales Order</span><textarea id=\"sql-editor\" rows=\"9\">SELECT * FROM ORDR;</textarea></label><div style=\"display:flex;justify-content:flex-end;gap:10px;flex-wrap:wrap;margin-top:10px\"><button type=\"button\" id=\"sql-copy\">Copy SQL query</button><button type=\"button\" id=\"sql-run\" disabled>Run SQL</button></div><p id=\"sql-status\" role=\"status\">Loading practice database...</p><div id=\"sql-output\" style=\"overflow:auto\"></div><h2>Practice exercises</h2><pre>SELECT * FROM OCRD;\\nSELECT ItemCode, OnHand FROM OITM;\\nSELECT H.DocNum,L.ItemCode,L.Quantity FROM ORDR H JOIN RDR1 L ON H.DocEntry=L.DocEntry;\\nSELECT SUM(DocTotal) FROM ORDR;</pre></article></div><script src=\"https://cdn.jsdelivr.net/npm/sql.js@1.13.0/dist/sql-wasm.js\"></script><script type=\"module\">const status=document.getElementById('sql-status'),editor=document.getElementById('sql-editor'),out=document.getElementById('sql-output'),run=document.getElementById('sql-run');document.getElementById('sql-copy').onclick=async()=>{try{await navigator.clipboard.writeText(editor.value);status.textContent='SQL query copied.'}catch(e){editor.focus();editor.select();status.textContent='Select and copy the query manually.'}};let db;try{const SQL=await initSqlJs({locateFile:f=>'https://cdn.jsdelivr.net/npm/sql.js@1.13.0/dist/'+f});db=new SQL.Database();db.run(\"CREATE TABLE OCRD(CardCode TEXT,CardName TEXT,CardType TEXT); INSERT INTO OCRD VALUES ('C001','Alpha Labs','C'),('C002','Beta Pharma','C'),('V001','Global Supplies','S'); CREATE TABLE OITM(ItemCode TEXT,ItemName TEXT,OnHand REAL); INSERT INTO OITM VALUES ('I001','Sample A',100),('I002','Sample B',50); CREATE TABLE ORDR(DocEntry INTEGER,DocNum INTEGER,DocDate TEXT,CardCode TEXT,CardName TEXT,DocTotal REAL,CANCELED TEXT); INSERT INTO ORDR VALUES (1,1001,'2026-11-01','C001','Alpha Labs',1500,'N'),(2,1002,'2026-11-02','C002','Beta Pharma',2500,'N'); CREATE TABLE RDR1(DocEntry INTEGER,LineNum INTEGER,ItemCode TEXT,Quantity REAL,LineTotal REAL); INSERT INTO RDR1 VALUES (1,0,'I001',3,1500),(2,0,'I002',5,2500);\");db.run(\"CREATE TABLE OQUT(DocEntry INTEGER PRIMARY KEY,DocNum INTEGER,DocDate TEXT,CardCode TEXT,CardName TEXT,DocTotal REAL,DocStatus TEXT,CANCELED TEXT,ObjType TEXT); INSERT INTO OQUT VALUES(1,2301,'2026-11-03','C001','Alpha Labs',1500,'O','N','23'); CREATE TABLE QUT1(DocEntry INTEGER,LineNum INTEGER,ItemCode TEXT,Dscription TEXT,Quantity REAL,Price REAL,LineTotal REAL,OpenQty REAL,LineStatus TEXT,WhsCode TEXT,BaseType INTEGER,BaseEntry INTEGER,BaseLine INTEGER); INSERT INTO QUT1 VALUES(1,0,'I001','Sample A',3,500,1500,3,'O','01',-1,-1,-1); CREATE TABLE ODLN(DocEntry INTEGER PRIMARY KEY,DocNum INTEGER,DocDate TEXT,CardCode TEXT,CardName TEXT,DocTotal REAL,DocStatus TEXT,CANCELED TEXT,ObjType TEXT); INSERT INTO ODLN VALUES(1,1501,'2026-11-03','C001','Alpha Labs',1500,'O','N','15'); CREATE TABLE DLN1(DocEntry INTEGER,LineNum INTEGER,ItemCode TEXT,Dscription TEXT,Quantity REAL,Price REAL,LineTotal REAL,OpenQty REAL,LineStatus TEXT,WhsCode TEXT,BaseType INTEGER,BaseEntry INTEGER,BaseLine INTEGER); INSERT INTO DLN1 VALUES(1,0,'I001','Sample A',3,500,1500,0,'C','01',17,1,0); CREATE TABLE OINV(DocEntry INTEGER PRIMARY KEY,DocNum INTEGER,DocDate TEXT,CardCode TEXT,CardName TEXT,DocTotal REAL,DocStatus TEXT,CANCELED TEXT,ObjType TEXT); INSERT INTO OINV VALUES(1,1301,'2026-11-03','C001','Alpha Labs',1500,'O','N','13'); CREATE TABLE INV1(DocEntry INTEGER,LineNum INTEGER,ItemCode TEXT,Dscription TEXT,Quantity REAL,Price REAL,LineTotal REAL,OpenQty REAL,LineStatus TEXT,WhsCode TEXT,BaseType INTEGER,BaseEntry INTEGER,BaseLine INTEGER); INSERT INTO INV1 VALUES(1,0,'I001','Sample A',3,500,1500,0,'C','01',15,1,0); CREATE TABLE ORIN(DocEntry INTEGER PRIMARY KEY,DocNum INTEGER,DocDate TEXT,CardCode TEXT,CardName TEXT,DocTotal REAL,DocStatus TEXT,CANCELED TEXT,ObjType TEXT); INSERT INTO ORIN VALUES(1,1401,'2026-11-03','C001','Alpha Labs',1500,'O','N','14'); CREATE TABLE RIN1(DocEntry INTEGER,LineNum INTEGER,ItemCode TEXT,Dscription TEXT,Quantity REAL,Price REAL,LineTotal REAL,OpenQty REAL,LineStatus TEXT,WhsCode TEXT,BaseType INTEGER,BaseEntry INTEGER,BaseLine INTEGER); INSERT INTO RIN1 VALUES(1,0,'I001','Sample A',3,500,1500,0,'C','01',13,1,0); CREATE TABLE OPRQ(DocEntry INTEGER PRIMARY KEY,DocNum INTEGER,DocDate TEXT,CardCode TEXT,CardName TEXT,DocTotal REAL,DocStatus TEXT,CANCELED TEXT,ObjType TEXT); INSERT INTO OPRQ VALUES(1,9001,'2026-11-03','V001','Global Supplies',1500,'O','N','1470000113'); CREATE TABLE PRQ1(DocEntry INTEGER,LineNum INTEGER,ItemCode TEXT,Dscription TEXT,Quantity REAL,Price REAL,LineTotal REAL,OpenQty REAL,LineStatus TEXT,WhsCode TEXT,BaseType INTEGER,BaseEntry INTEGER,BaseLine INTEGER); INSERT INTO PRQ1 VALUES(1,0,'I001','Sample A',3,500,1500,3,'O','01',-1,-1,-1); CREATE TABLE OPOR(DocEntry INTEGER PRIMARY KEY,DocNum INTEGER,DocDate TEXT,CardCode TEXT,CardName TEXT,DocTotal REAL,DocStatus TEXT,CANCELED TEXT,ObjType TEXT); INSERT INTO OPOR VALUES(1,2201,'2026-11-03','V001','Global Supplies',1500,'O','N','22'); CREATE TABLE POR1(DocEntry INTEGER,LineNum INTEGER,ItemCode TEXT,Dscription TEXT,Quantity REAL,Price REAL,LineTotal REAL,OpenQty REAL,LineStatus TEXT,WhsCode TEXT,BaseType INTEGER,BaseEntry INTEGER,BaseLine INTEGER); INSERT INTO POR1 VALUES(1,0,'I001','Sample A',3,500,1500,3,'O','01',1470000113,1,0); CREATE TABLE OPDN(DocEntry INTEGER PRIMARY KEY,DocNum INTEGER,DocDate TEXT,CardCode TEXT,CardName TEXT,DocTotal REAL,DocStatus TEXT,CANCELED TEXT,ObjType TEXT); INSERT INTO OPDN VALUES(1,2001,'2026-11-03','V001','Global Supplies',1500,'O','N','20'); CREATE TABLE PDN1(DocEntry INTEGER,LineNum INTEGER,ItemCode TEXT,Dscription TEXT,Quantity REAL,Price REAL,LineTotal REAL,OpenQty REAL,LineStatus TEXT,WhsCode TEXT,BaseType INTEGER,BaseEntry INTEGER,BaseLine INTEGER); INSERT INTO PDN1 VALUES(1,0,'I001','Sample A',3,500,1500,0,'C','01',22,1,0); CREATE TABLE OPCH(DocEntry INTEGER PRIMARY KEY,DocNum INTEGER,DocDate TEXT,CardCode TEXT,CardName TEXT,DocTotal REAL,DocStatus TEXT,CANCELED TEXT,ObjType TEXT); INSERT INTO OPCH VALUES(1,1801,'2026-11-03','V001','Global Supplies',1500,'O','N','18'); CREATE TABLE PCH1(DocEntry INTEGER,LineNum INTEGER,ItemCode TEXT,Dscription TEXT,Quantity REAL,Price REAL,LineTotal REAL,OpenQty REAL,LineStatus TEXT,WhsCode TEXT,BaseType INTEGER,BaseEntry INTEGER,BaseLine INTEGER); INSERT INTO PCH1 VALUES(1,0,'I001','Sample A',3,500,1500,0,'C','01',20,1,0); CREATE TABLE ORPC(DocEntry INTEGER PRIMARY KEY,DocNum INTEGER,DocDate TEXT,CardCode TEXT,CardName TEXT,DocTotal REAL,DocStatus TEXT,CANCELED TEXT,ObjType TEXT); INSERT INTO ORPC VALUES(1,1901,'2026-11-03','V001','Global Supplies',1500,'O','N','19'); CREATE TABLE RPC1(DocEntry INTEGER,LineNum INTEGER,ItemCode TEXT,Dscription TEXT,Quantity REAL,Price REAL,LineTotal REAL,OpenQty REAL,LineStatus TEXT,WhsCode TEXT,BaseType INTEGER,BaseEntry INTEGER,BaseLine INTEGER); INSERT INTO RPC1 VALUES(1,0,'I001','Sample A',3,500,1500,0,'C','01',18,1,0); CREATE TABLE OIGN(DocEntry INTEGER PRIMARY KEY,DocNum INTEGER,DocDate TEXT,CardCode TEXT,CardName TEXT,DocTotal REAL,DocStatus TEXT,CANCELED TEXT,ObjType TEXT); INSERT INTO OIGN VALUES(1,5901,'2026-11-03','V001','Global Supplies',1500,'O','N','59'); CREATE TABLE IGN1(DocEntry INTEGER,LineNum INTEGER,ItemCode TEXT,Dscription TEXT,Quantity REAL,Price REAL,LineTotal REAL,OpenQty REAL,LineStatus TEXT,WhsCode TEXT,BaseType INTEGER,BaseEntry INTEGER,BaseLine INTEGER); INSERT INTO IGN1 VALUES(1,0,'I001','Sample A',3,500,1500,0,'C','01',-1,-1,-1); CREATE TABLE OIGE(DocEntry INTEGER PRIMARY KEY,DocNum INTEGER,DocDate TEXT,CardCode TEXT,CardName TEXT,DocTotal REAL,DocStatus TEXT,CANCELED TEXT,ObjType TEXT); INSERT INTO OIGE VALUES(1,6001,'2026-11-03','V001','Global Supplies',1500,'O','N','60'); CREATE TABLE IGE1(DocEntry INTEGER,LineNum INTEGER,ItemCode TEXT,Dscription TEXT,Quantity REAL,Price REAL,LineTotal REAL,OpenQty REAL,LineStatus TEXT,WhsCode TEXT,BaseType INTEGER,BaseEntry INTEGER,BaseLine INTEGER); INSERT INTO IGE1 VALUES(1,0,'I001','Sample A',3,500,1500,0,'C','01',-1,-1,-1); CREATE TABLE OWTR(DocEntry INTEGER PRIMARY KEY,DocNum INTEGER,DocDate TEXT,CardCode TEXT,CardName TEXT,DocTotal REAL,DocStatus TEXT,CANCELED TEXT,ObjType TEXT); INSERT INTO OWTR VALUES(1,6701,'2026-11-03','V001','Global Supplies',1500,'O','N','67'); CREATE TABLE WTR1(DocEntry INTEGER,LineNum INTEGER,ItemCode TEXT,Dscription TEXT,Quantity REAL,Price REAL,LineTotal REAL,OpenQty REAL,LineStatus TEXT,WhsCode TEXT,BaseType INTEGER,BaseEntry INTEGER,BaseLine INTEGER); INSERT INTO WTR1 VALUES(1,0,'I001','Sample A',3,500,1500,0,'C','01',-1,-1,-1); CREATE TABLE ODRF(DocEntry INTEGER PRIMARY KEY,DocNum INTEGER,DocDate TEXT,CardCode TEXT,CardName TEXT,DocTotal REAL,DocStatus TEXT,CANCELED TEXT,ObjType TEXT); INSERT INTO ODRF VALUES(1,11201,'2026-11-03','V001','Global Supplies',1500,'O','N','112'); CREATE TABLE DRF1(DocEntry INTEGER,LineNum INTEGER,ItemCode TEXT,Dscription TEXT,Quantity REAL,Price REAL,LineTotal REAL,OpenQty REAL,LineStatus TEXT,WhsCode TEXT,BaseType INTEGER,BaseEntry INTEGER,BaseLine INTEGER); INSERT INTO DRF1 VALUES(1,0,'I001','Sample A',3,500,1500,0,'C','01',-1,-1,-1); CREATE TABLE OWHS(WhsCode TEXT,WhsName TEXT); INSERT INTO OWHS VALUES('01','Main Warehouse'); CREATE TABLE OITW(ItemCode TEXT,WhsCode TEXT,OnHand REAL,IsCommited REAL,OnOrder REAL); INSERT INTO OITW VALUES('I001','01',100,3,10); CREATE TABLE OITB(ItmsGrpCod INTEGER,ItmsGrpNam TEXT); INSERT INTO OITB VALUES(100,'Sample Items'); CREATE TABLE OACT(AcctCode TEXT,AcctName TEXT); INSERT INTO OACT VALUES('110000','Bank'); CREATE TABLE OJDT(TransId INTEGER,RefDate TEXT,Memo TEXT); INSERT INTO OJDT VALUES(1,'2026-11-03','Sample invoice'); CREATE TABLE JDT1(TransId INTEGER,Line_ID INTEGER,Account TEXT,ShortName TEXT,Debit REAL,Credit REAL); INSERT INTO JDT1 VALUES(1,0,'110000','110000',1500,0),(1,1,'400000','400000',0,1500); CREATE TABLE ORCT(DocEntry INTEGER,DocNum INTEGER,CardCode TEXT,DocTotal REAL,Canceled TEXT); INSERT INTO ORCT VALUES(1,5001,'C001',1500,'N'); CREATE TABLE RCT2(DocNum INTEGER,DocEntry INTEGER,InvType INTEGER,SumApplied REAL); INSERT INTO RCT2 VALUES(1,1,13,1500); CREATE TABLE OVPM(DocEntry INTEGER,DocNum INTEGER,CardCode TEXT,DocTotal REAL,Canceled TEXT); INSERT INTO OVPM VALUES(1,6001,'V001',1500,'N'); CREATE TABLE VPM2(DocNum INTEGER,DocEntry INTEGER,InvType INTEGER,SumApplied REAL); INSERT INTO VPM2 VALUES(1,1,18,1500); CREATE TABLE OWOR(DocEntry INTEGER,DocNum INTEGER,ItemCode TEXT,PlannedQty REAL,CmpltQty REAL,Status TEXT); INSERT INTO OWOR VALUES(1,7001,'I002',10,5,'R'); CREATE TABLE WOR1(DocEntry INTEGER,LineNum INTEGER,ItemCode TEXT,PlannedQty REAL,IssuedQty REAL); INSERT INTO WOR1 VALUES(1,0,'I001',20,10); CREATE TABLE OITT(Code TEXT,Name TEXT,Quantity REAL); INSERT INTO OITT VALUES('I002','Sample B',1); CREATE TABLE ITT1(Father TEXT,Code TEXT,Quantity REAL); INSERT INTO ITT1 VALUES('I002','I001',2); CREATE TABLE OSLP(SlpCode INTEGER,SlpName TEXT); INSERT INTO OSLP VALUES(1,'Demo Salesperson'); CREATE TABLE OHEM(empID INTEGER,firstName TEXT,lastName TEXT); INSERT INTO OHEM VALUES(1,'Demo','Employee'); CREATE TABLE OCTG(GroupNum INTEGER,PymntGroup TEXT); INSERT INTO OCTG VALUES(1,'Net 30'); CREATE TABLE ORTT(RateDate TEXT,Currency TEXT,Rate REAL); INSERT INTO ORTT VALUES('2026-11-03','USD',85); CREATE TABLE OITR(ReconNum INTEGER,ReconDate TEXT,Canceled TEXT); INSERT INTO OITR VALUES(1,'2026-11-03','N'); CREATE TABLE ITR1(ReconNum INTEGER,TransId INTEGER,SrcObjTyp INTEGER,SrcObjAbs INTEGER,ReconSum REAL); INSERT INTO ITR1 VALUES(1,1,13,1,1500); CREATE TABLE NNM1(Series INTEGER,SeriesName TEXT,ObjectCode TEXT); INSERT INTO NNM1 VALUES(1,'Demo','17'); CREATE TABLE OSCL(callID INTEGER,customer TEXT,subject TEXT,status INTEGER); INSERT INTO OSCL VALUES(1,'C001','Sample service call',-3); ALTER TABLE OITM ADD COLUMN AssetItem TEXT DEFAULT 'N'; ALTER TABLE ORDR ADD COLUMN DocStatus TEXT DEFAULT 'O'; ALTER TABLE RDR1 ADD COLUMN WhsCode TEXT DEFAULT '01'; ALTER TABLE RDR1 ADD COLUMN Price REAL DEFAULT 500; INSERT INTO OACT VALUES('400000','Revenue');\");db.run(\"INSERT INTO OCRD VALUES ('C003','Delta Research','C'),('V002','Metro Chemicals','S'); INSERT INTO OITM(ItemCode,ItemName,OnHand) VALUES ('I003','Sample C',250),('I004','Sample D',80); INSERT INTO ORDR(DocEntry,DocNum,DocDate,CardCode,CardName,DocTotal,CANCELED,DocStatus) VALUES (3,1003,'2026-11-04','C003','Delta Research',6000,'N','O'),(4,1004,'2026-11-05','C001','Alpha Labs',4000,'N','O'); INSERT INTO RDR1(DocEntry,LineNum,ItemCode,Quantity,LineTotal,WhsCode,Price) VALUES(3,0,'I003',10,6000,'01',600),(4,0,'I004',8,4000,'01',500); INSERT INTO OITW VALUES('I002','01',50,5,20),('I003','01',250,10,0),('I004','01',80,8,0);\");const joinChecks=[['INNER','SELECT T0.DocNum,T1.ItemCode FROM ORDR T0 INNER JOIN RDR1 T1 ON T0.DocEntry=T1.DocEntry'],['LEFT','SELECT T0.ItemCode,T1.OnHand FROM OITM T0 LEFT JOIN OITW T1 ON T0.ItemCode=T1.ItemCode'],['RIGHT','SELECT T0.CardName,T1.DocNum FROM OCRD T0 RIGHT JOIN ORDR T1 ON T0.CardCode=T1.CardCode'],['FULL','SELECT T0.CardName,T1.DocNum FROM OCRD T0 FULL OUTER JOIN ORDR T1 ON T0.CardCode=T1.CardCode'],['CROSS','SELECT T0.ItemCode,T1.WhsCode FROM OITM T0 CROSS JOIN OWHS T1']];const joinResults=joinChecks.map(([name,query])=>{try{db.exec(query);return name+' OK';}catch(e){return name+' FAILED: '+e.message;}});status.textContent='Practice database ready | TOP v2 | '+joinResults.join(' | ');run.disabled=false;const tableNames={OCRD:'Business Partner Master Data',OITM:'Item Master Data',ORDR:'Sales Order',RDR1:'Sales Order Rows',OQUT:'Sales Quotation',QUT1:'Sales Quotation Rows',ODLN:'Delivery',DLN1:'Delivery Rows',OINV:'A/R Invoice',INV1:'A/R Invoice Rows',ORIN:'A/R Credit Memo',RIN1:'A/R Credit Memo Rows',OPRQ:'Purchase Request',PRQ1:'Purchase Request Rows',OPOR:'Purchase Order',POR1:'Purchase Order Rows',OPDN:'Goods Receipt PO',PDN1:'Goods Receipt PO Rows',OPCH:'A/P Invoice',PCH1:'A/P Invoice Rows',ORPC:'A/P Credit Memo',RPC1:'A/P Credit Memo Rows',OIGN:'Goods Receipt',IGN1:'Goods Receipt Rows',OIGE:'Goods Issue',IGE1:'Goods Issue Rows',OWTR:'Inventory Transfer',WTR1:'Inventory Transfer Rows',ODRF:'Document Drafts',DRF1:'Document Draft Rows',OWHS:'Warehouses',OITW:'Item Warehouse Data',OITB:'Item Groups',OACT:'Chart of Accounts',OJDT:'Journal Entry',JDT1:'Journal Entry Rows',ORCT:'Incoming Payments',RCT2:'Incoming Payment Invoices',OVPM:'Outgoing Payments',VPM2:'Outgoing Payment Invoices',OWOR:'Production Order',WOR1:'Production Order Rows',OITT:'Bill of Materials',ITT1:'Bill of Materials Components',OSLP:'Sales Employees',OHEM:'Employee Master Data',OCTG:'Payment Terms',ORTT:'Exchange Rates',OITR:'Internal Reconciliation',ITR1:'Internal Reconciliation Rows',NNM1:'Document Numbering Series',OSCL:'Service Calls'};const picker=document.getElementById('sql-table');for(const row of db.exec(\"SELECT name FROM sqlite_master WHERE type='table' ORDER BY name\")[0].values){const opt=document.createElement('option');opt.value=row[0];opt.textContent=row[0]+' – '+(tableNames[row[0]]||row[0]);picker.append(opt);}picker.value='ORDR';picker.onchange=()=>{if(picker.value){document.getElementById('sql-selected-name').textContent=picker.value+' – '+(tableNames[picker.value]||picker.value);editor.value='SELECT * FROM '+picker.value+';';run.click();}};}catch(e){status.textContent='Unable to load SQL engine: '+e.message;}run.onclick=()=>{out.replaceChildren();try{const q=editor.value.trim();if(!/^SELECT\\b/i.test(q)||q.replace(/;\\s*$/,'').includes(';'))throw Error('Enter one SELECT statement only.');let executable=q;const top=q.match(/^SELECT[ \\t\\r\\n]+(DISTINCT[ \\t\\r\\n]+)?TOP[ \\t\\r\\n]*(?:[(][ \\t\\r\\n]*([0-9]+)[ \\t\\r\\n]*[)]|([0-9]+))[ \\t\\r\\n]+([^]+)$/i);if(top){let body=top[4].trim();if(body.endsWith(';'))body=body.slice(0,-1);executable='SELECT '+(top[1]||'')+body+' LIMIT '+(top[2]||top[3]);}const result=db.exec(executable);for(const set of result){const table=document.createElement('table');table.style.cssText='width:100%;border-collapse:collapse';for(const row of [set.columns,...set.values.slice(0,200)]){const tr=table.insertRow();for(const value of row){const cell=tr.insertCell();cell.textContent=value===null?'NULL':String(value);cell.style.cssText='padding:10px;border:1px solid #cbd5e1';}}out.append(table);}status.textContent=result.length?result[0].values.length+' rows returned (display limit 200)':'No rows returned';}catch(e){status.textContent=e.message+' | SQL practice v2';}};</script>");
