for(const [slug,title,desc] of utilitySpecs){const actions=slug==='case-converter'?['Uppercase','Lowercase','Title case']:slug==='remove-duplicate-lines'?['Remove duplicates']:['Encode','Decode'];const script=function(){const input=document.getElementById('utility-input'),out=document.getElementById('utility-output');document.querySelectorAll('[data-action]').forEach(b=>b.onclick=()=>{try{const s=input.value,a=b.dataset.action,k=document.body.dataset.kind;let v;if(k==='case-converter')v=a==='Uppercase'?s.toUpperCase():a==='Lowercase'?s.toLowerCase():s.toLowerCase().replace(/(^|\s)\S/g,x=>x.toUpperCase());else if(k==='remove-duplicate-lines')v=[...new Set(s.split(/\r?\n/))].join('\n');else if(k==='url-encoder-decoder')v=a==='Encode'?encodeURIComponent(s):decodeURIComponent(s);else v=a==='Encode'?btoa(Array.from(new TextEncoder().encode(s),x=>String.fromCharCode(x)).join('')):new TextDecoder('utf-8',{fatal:true}).decode(Uint8Array.from(atob(s),x=>x.charCodeAt(0)));out.value=v;}catch(e){out.value='Error: '+e.message;}});};page(slug,title,desc,'<section class="panel"><label>Input<textarea id="utility-input" rows="8"></textarea></label>'+actions.map(a=>'<button type="button" data-action="'+a+'">'+a+'</button>').join('')+'<label>Result<textarea id="utility-output" rows="8" readonly></textarea></label></section><h2>How to use</h2><p>Paste your text, choose an action and copy the result. Processing takes place in your browser. Base64 and URL encoding are not encryption.</p><script>('+script.toString()+')()</script>',slug);}
